UPDATE mall_product
category_id = #{categoryId}, name = #{name}, description = #{description}, cover = #{cover}, price = #{price}, original_price = #{originalPrice}, stock = #{stock}, unit = #{unit}, status = #{status}, is_hot = #{isHot}, is_new = #{isNew},
WHERE id = #{id}

mapper.select:
SELECT p.*, pc.name AS category_name
FROM mall_product p
LEFT JOIN product_category pc ON pc.id = p.category_id

    AND p.category_id = #{categoryId}
    AND p.name LIKE CONCAT('%', #{name}, '%')
    AND p.status = #{status}
    AND p.is_hot = #{isHot}
    AND p.is_new = #{isNew}

        AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.description LIKE CONCAT('%', #{keyword}, '%'))

    AND p.create_time BETWEEN #{startTime} AND #{endTime}

ORDER BY p.create_time DESC
LIMIT #{current}, #{size}

SELECT COUNT(*) FROM mall_product p

    AND p.category_id = #{categoryId}
    AND p.name LIKE CONCAT('%', #{name}, '%')
    AND p.status = #{status}
    AND p.is_hot = #{isHot}
    AND p.is_new = #{isNew}

        AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.description LIKE CONCAT('%', #{keyword}, '%'))

    AND p.create_time BETWEEN #{startTime} AND #{endTime}

SELECT id, name, sales_count as salesCount, price
FROM mall_product WHERE status = 1
ORDER BY sales_count DESC LIMIT #{limit}
